/*
 * 由 tools/subset_font.py 从原始 font20.c 裁剪而来。
 * 字形数据逐像素来自原字体，渲染效果不变。
 *
 * 原格式按「码点 - min」直接索引一张 65501 项的偏移表（256 KB），
 * 与实际字形数无关。这里改为「升序码点数组 + 平行偏移数组 + 二分查找」，
 * 表的大小随字形数走。
 *
 * 只包含界面实际用到的 388 个字形。**新增中文文案时若用到表外的字，
 * 会渲染成空白**——tools/check_charset.py 会在构建前拦下这种情况。
 */
#include "lvgl.h"

