/* 码点升序，二分查找。找不到返回 -1。 */
static int font_find(uint32_t u)
{
    int lo = 0, hi = (int)FONT_N - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (font_cp[mid] == u) return mid;
        if (font_cp[mid] < u) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

static const uint8_t *__user_font_get_bitmap(const lv_font_t *font, uint32_t unicode_letter)
{
    (void)font;
    int i = font_find(unicode_letter);
    if (i < 0) return NULL;
    return &font_blob[font_off[i] + sizeof(glyph_dsc_t)];
}

static bool __user_font_get_glyph_dsc(const lv_font_t *font, lv_font_glyph_dsc_t *dsc_out,
                                     uint32_t unicode_letter, uint32_t unicode_letter_next)
{
    (void)font; (void)unicode_letter_next;
    int i = font_find(unicode_letter);
    if (i < 0) return false;
    const glyph_dsc_t *g = (const glyph_dsc_t *)&font_blob[font_off[i]];
    dsc_out->adv_w = g->adv_w;
    dsc_out->box_w = g->box_w;
    dsc_out->box_h = g->box_h;
    dsc_out->ofs_x = g->ofs_x;
    dsc_out->ofs_y = g->ofs_y;
    dsc_out->bpp   = FONT_BPP;
    return true;
}

lv_font_t font20 = {
    .get_glyph_bitmap = __user_font_get_bitmap,
    .get_glyph_dsc = __user_font_get_glyph_dsc,
    .line_height = 26,
    .base_line = 0,
};
